        {
            var project=SwordShieldProject.Open(Fixture(temp));window.PresentProject(project);var hp=(System.Windows.Controls.TextBox)window.FindName("SwitchPersonalField0");var attack=(System.Windows.Controls.TextBox)window.FindName("SwitchPersonalField1");hp.Text="99";attack.Text="88";check(((System.Windows.Controls.TextBlock)window.FindName("SwitchPersonalBst")).Text.Contains("365")&&((System.Windows.Controls.TextBlock)window.FindName("SwitchPersonalState")).Text=="Cambios sin guardar","Switch_Parity_UIPersonalBstAndDirtyStateUpdateWhileEditing");((System.Windows.Controls.Button)window.FindName("SwitchApply")).RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));check(project.Read(1).Values[0]==99&&project.Read(1).Values[1]==88,"Switch_Parity_UIFullPersonalFormSavesThroughSharedSession");
            var adapter=new SwordShieldRecordEditor(project,SwordShieldDataSection.TrainerTeams);var view=new RecordEditorView(adapter);check(((System.Windows.Controls.ListBox)view.FindName("RecordList")).Items.Count==1&&view.FieldControls.ContainsKey("P0.Species")&&view.FieldControls.ContainsKey("P0.Move1"),"Switch_Parity_UITrainerUsesOriginalRecordViewAndFieldGroups");
            check(view.OptionControls.ContainsKey("CHK_ProgressiveBST")&&view.OptionControls.ContainsKey("GlobalItems.Smart")&&view.OptionControls.ContainsKey("GlobalMoves.Better"),"Switch_Parity_UITrainerExposesBstMovesAndSmartItemsInSharedMenus");
