    internal static void Probe(string root)
    {
        var project=SwordShieldProject.Open(root);var trainers=project.ReadData(SwordShieldDataSection.TrainerTeams).Select(c=>c.Entry).Distinct().ToArray();var classified=trainers.Where(id=>project.TrainerKind(id)!="Normal").ToArray();if(!classified.Any(id=>project.TrainerKind(id)=="Importantes · Rivales"))throw new Exception("No rival encounters classified.");Console.WriteLine("PASS Switch_Tables_RealTrainerClassification: "+string.Join(" | ",classified.GroupBy(project.TrainerKind).Select(g=>g.Key+": "+g.Count())));foreach(int id in classified)Console.WriteLine("Trainer #"+id+" · "+project.TrainerKind(id)+" · "+project.TrainerName(id));var canonical=project.ReadData(SwordShieldDataSection.Moves);if(canonical.Count(c=>c.Entry==1)!=6||canonical.Single(c=>c.Entry==1&&c.Field=="Categoría").Value!=1)throw new Exception("Move schema/category mismatch.");foreach(bool items in new[]{false,true}){var world=new SwordShieldWorldEditor(project,items);if(world.Entries.Count==0)throw new Exception("Empty world editor.");var groups=world.Read(world.Entries[0].Id);var skip=EditorValues.Flatten(world.RandomOptions);skip["Visible"]=skip["Hidden"]=0;if(world.Preview(skip,new[]{world.Entries[0].Id}).Changes.Count!=0)throw new Exception("Unchecked world actions changed data.");var values=EditorValues.Flatten(groups);world.Save(world.Entries[0].Id,values);Console.WriteLine("PASS Switch_Parity_RealSharedWorldEditor_"+(items?"FieldItems":"Encounters")+": "+world.Entries.Count+" regions");}var wild=project.PreviewGameplay(new SwordShieldGameplayOptions(12345,VisibleEncounters:true,HiddenEncounters:true){ProgressiveBst=true});Console.WriteLine("PASS Switch_Parity_RealAllWildProgressiveBstPreview: "+wild.Result.Changes.Count+" changes");var allTeams=project.PreviewGameplay(new SwordShieldGameplayOptions(12345,Trainers:true){ProgressiveBst=true,TrainerRules=new(){BetterMovesets=true,SmartItems=true}});Console.WriteLine("PASS Switch_Parity_RealAllTrainerBstMovesItemsPreview: "+allTeams.Result.Changes.Count+" changes");var rules=new SwordShieldTrainerOptions{BetterMovesets=true,SmartItems=true};var options=new SwordShieldGameplayOptions(12345,Trainers:true){TrainerScope=new[]{32},TrainerRules=rules,ProgressiveBst=true};var preview=project.PreviewGameplay(options);if(preview.Result.Changes.Count==0)throw new Exception("No real changes.");project.ApplyGameplay(preview);Console.WriteLine("PASS Switch_Parity_RealSwordTrainerBstMovesItemsPreviewAndApplyInMemory: "+preview.Result.Changes.Count+" changes; source read-only, gameplay NOT tested.");
    }
